    public static unsafe class HopcroftKarpDfs
    {
        public static bool Run(int u, int nLeft, int nRight, int* head, int* to, int* next, int* pairU, int* pairV, int* dist, int* it)
        {
            if (u == -1) return true;
            for (int e = it[u]; e != 0; e = next[e])
