namespace IAFahim.Graph.Flow
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class MinCostFlowPrimalDual
    {
        private const int NullEdge = 0;
        private const long Unreached = long.MaxValue;
        private const int NoParent = -1;

        public static long Run(int n, int s, int t, int* head, int* to, int* next, int* cap, int* cost, int* flow)
        {
            long totalCost = 0;
            for (int i = 0; i < n * 2; i++) flow[i] = 0;
            long* dist = stackalloc long[n];
            int* parent = stackalloc int[n];
            int* parentEdge = stackalloc int[n];
            long* pot = stackalloc long[n];
            for (int i = 0; i < n; i++) pot[i] = 0;
            int* level = stackalloc int[n];
            for (int i = 0; i < n; i++) level[i] = 0;

            while (true)
            {
                for (int i = 0; i < n; i++) { dist[i] = Unreached; parent[i] = NoParent; }
                dist[s] = 0;
                int* q = stackalloc int[n];
                int qh = 0, qt = 0;
                q[qt++] = s;

                while (qh < qt)
                {
                    int u = q[qh++];
                    for (int e = head[u]; e != NullEdge; e = next[e])
                        Relax(u, e, to, next, cap, cost, flow, dist, parent, parentEdge, pot, q, ref qt);
                }
                if (dist[t] == Unreached) break;
                for (int i = 0; i < n; i++) if (dist[i] < Unreached) pot[i] += dist[i];

                int add = FindBottleneck(s, t, parent, parentEdge, cap, flow);
                Augment(s, t, add, parent, parentEdge, cost, flow, ref totalCost);
            }
            return totalCost;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Relax(int u, int e, int* to, int* next, int* cap, int* cost, int* flow, long* dist, int* parent, int* parentEdge, long* pot, int* q, ref int qt)
        {
            if (cap[e] - flow[e] <= 0) return;
            int v = to[e];
            long nd = dist[u] + cost[e] + pot[u] - pot[v];
            if (nd < dist[v]) { dist[v] = nd; parent[v] = u; parentEdge[v] = e; q[qt++] = v; }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int FindBottleneck(int s, int t, int* parent, int* parentEdge, int* cap, int* flow)
        {
            int add = int.MaxValue;
            for (int v = t; v != s; v = parent[v]) add = Math.Min(add, cap[parentEdge[v]] - flow[parentEdge[v]]);
            return add;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void Augment(int s, int t, int add, int* parent, int* parentEdge, int* cost, int* flow, ref long totalCost)
        {
            for (int v = t; v != s; v = parent[v]) { int e = parentEdge[v]; flow[e] += add; flow[e ^ 1] -= add; totalCost += (long)cost[e] * add; }
        }
    }
}

