        }

        private static int FindPathMinCapacity(int s, int t, int* parent, int* parentEdge, int* cap)
        {
            int add = int.MaxValue;
            for (int v = t; v != s; v = parent[v]) add = Math.Min(add, cap[parentEdge[v]]);
